-- Corrections issues de la relecture des fiches par Claude (octobre 2026),
-- voir scripts/verification/RAPPORT-RELECTURE-CLAUDE.md.
-- Chaque correction remplace un passage exact de la fiche ; elle n'est
-- appliquée que si ce passage figure le nombre de fois attendu (sinon :
-- tout le lot est annulé). Chaque fiche modifiée reçoit une
-- ligne dans le journal public des corrections (corrections_log).
-- Idempotent : une correction déjà appliquée n'est pas rejouée.

drop table if exists pg_temp._corr, pg_temp._journal;
create temporary table _corr (i int, cle text, o text, n text, nb int);
create temporary table _journal (cle text, criticite text, resume text);

do $$
declare c record; t text; k int; modifiees text[] := '{}'; problemes text[] := '{}';
begin
  for c in select * from _corr order by i loop
    select d.presentation_json::text into t from public.documents d where d.fiche_key = c.cle;
    if t is null then raise exception 'Fiche absente : %', c.cle; end if;
    k := (length(t) - length(replace(t, c.o, ''))) / greatest(length(c.o), 1);
    if position(c.n in t) > 0 and (k = 0 or position(c.o in c.n) > 0) then
      null; -- déjà corrigée
    elsif k = c.nb then
      update public.documents d set presentation_json = replace(t, c.o, c.n)::jsonb where d.fiche_key = c.cle;
      modifiees := array_append(modifiees, c.cle);
    else
      problemes := array_append(problemes, format('%s (%s) : %s fois au lieu de %s', c.i, c.cle, k, c.nb));
    end if;
  end loop;
  if cardinality(problemes) > 0 then
    raise exception 'Rien n''est appliqué. Passages introuvables : %', array_to_string(problemes, ' ; ');
  end if;
  select d.id, j.criticite, j.resume
    from _journal j join public.documents d on d.fiche_key = j.cle
   where j.cle = any(modifiees)
     and not exists (select 1 from public.corrections_log l where l.document_id = d.id and l.resume = j.resume);
end $$;
drop table if exists pg_temp._corr, pg_temp._journal;
