(0, 'allergie_prevention', '(&gt; 25 microg/mL)', '(&gt; 25 µg/L)', 1),
(1, 'allergie_prevention', 'IDR CM (mg/mL)', 'IDR CM (µg/mL)', 2),
(2, 'anaphylaxie', '[{"t": "p", "html": "Régulièrement (20-30%)", "style": "cell"}, {"t": "p", "html": "Kiwi, banane, avocat, châtaigne", "style": "cell"}], [{"t": "p", "html": "Occasionnellement (&lt; 10%)", "style": "cell"}, {"t": "p", "html": "Papaye, figue, fruits exotiques, sarrasin", "style": "cell"}], [{"t": "p", "html": "Rarement (&lt; 1%)", "style": "cell"}, {"t": "p", "html": "Tomate, pêche, poivron", "style": "cell"}]', '[{"t": "p", "html": "Régulièrement (20-30%)", "style": "cell"}, {"t": "p", "html": "Kiwi, banane, avocat, papaye", "style": "cell"}], [{"t": "p", "html": "Occasionnellement (&lt; 10%)", "style": "cell"}, {"t": "p", "html": "Châtaigne", "style": "cell"}], [{"t": "p", "html": "Rarement (&lt; 1%)", "style": "cell"}, {"t": "p", "html": "Figue, fruits exotiques, tomate, pêche, sarrasin, poivron…", "style": "cell"}]', 1),
(3, 'anticoagulants', '[{"t": "p", "html": "AOD anti-Xa (apixaban, édoxaban, rivaroxaban)", "style": "cell"}, {"t": "p", "html": "J-3 si fonction rénale normale ; J-5 si risque hémorragique très élevé (neurochirurgie intracrânienne, neuraxial)", "style": "cell"}, {"t": "chip", "label": "2+"}]', '[{"t": "p", "html": "AOD anti-Xa (apixaban, édoxaban, rivaroxaban)", "style": "cell"}, {"t": "p", "html": "J-3 si fonction rénale normale", "style": "cell"}, {"t": "chip", "label": "2+"}], [{"t": "p", "html": "AOD (anti-Xa ou dabigatran) — risque hémorragique très élevé (neurochirurgie intracrânienne, neuraxial)", "style": "cell"}, {"t": "p", "html": "J-5", "style": "cell"}, {"t": "chip", "label": "AE"}]', 1),
(4, 'anticoagulants', '[{"t": "p", "html": "3.3/5.5", "style": "cell_b"}, {"t": "p", "html": "Risque hémorragique élevé : arrêt AOD, dernière prise à J-3 (DFG normal), sans relais héparinique.", "style": "cell"}, {"t": "chip", "label": "2+"}, {"t": "p", "html": "Fort", "style": "cell_c"}]', '[{"t": "p", "html": "3.3", "style": "cell_b"}, {"t": "p", "html": "Risque hémorragique élevé : arrêt AOD, dernière prise à J-3 (DFG normal).", "style": "cell"}, {"t": "chip", "label": "2+"}, {"t": "p", "html": "Fort", "style": "cell_c"}], [{"t": "p", "html": "5.5", "style": "cell_b"}, {"t": "p", "html": "Ne pas réaliser de relais héparinique pré-procédural à l''arrêt des AOD.", "style": "cell"}, {"t": "chip", "label": "2-"}, {"t": "p", "html": "Fort", "style": "cell_c"}]', 1),
(5, 'anticoagulants', 'AOD en IRC sévère (DFGe 30-49) :', 'AOD en IRC modérée (DFGe 30-49) :', 1),
(6, 'hsa', 'Valeur normale décroissant avec l''âge :', 'Valeur normale croissant avec l''âge (seuil supérieur plus élevé chez le sujet âgé) :', 1),
(7, 'coronarien', '[{"t": "p", "html": "4. Capacité fonctionnelle & score de Lee", "style": "cell_b"}, {"t": "p", "html": "≥ 4 MET, asymptomatique → opérer (poursuite bêta-bloquant/statine en cours, ECG réalisé, pas de test de stress). &lt; 4 MET ou non évaluable → stratifier par le score de Lee.", "style": "cell"}], [{"t": "p", "html": "4a. 0-1 facteur de Lee", "style": "cell_b"}, {"t": "p", "html": "Opérer (sauf angor de novo classe I-II découvert en consultation d''anesthésie → avis cardiologique, décision collégiale du moment du bilan, ajustement du traitement).", "style": "cell"}], [{"t": "p", "html": "4b. ≥ 2 facteurs de Lee (chirurgie vasculaire) ou ≥ 3 facteurs (chirurgie intermédiaire/élevée non vasculaire)", "style": "cell_b"}, {"t": "p", "html": "La RFE française privilégie un test d''ischémie fonctionnelle (scintigraphie ou échographie de stress, discuté collégialement) plutôt que le simple contrôle de FC par bêta-bloquant retenu par certaines recommandations européennes.", "style": "cell"}]', '[{"t": "p", "html": "4. Score de Lee", "style": "cell_b"}, {"t": "p", "html": "Patient stable, chirurgie à risque intermédiaire ou élevé : stratifier d''abord par le score de Lee.", "style": "cell"}], [{"t": "p", "html": "4a. Lee 0-1 (chirurgie vasculaire) ou 0-2 (chirurgie non vasculaire)", "style": "cell_b"}, {"t": "p", "html": "Chirurgie sans examen spécialisé, optimisation du traitement médical préopératoire (sauf angor de novo classe I-II découvert en consultation d''anesthésie → avis cardiologique, décision collégiale du moment du bilan, ajustement du traitement).", "style": "cell"}], [{"t": "p", "html": "4b. Lee ≥ 2 (chirurgie vasculaire) ou ≥ 3 (chirurgie non vasculaire)", "style": "cell_b"}, {"t": "p", "html": "Évaluer la capacité fonctionnelle : bonne (≥ 4 MET) → chirurgie sans examen spécialisé ; mauvaise (&lt; 4 MET) → test d''ischémie. La RFE française privilégie un test d''ischémie fonctionnelle (scintigraphie ou échographie de stress, discuté collégialement) plutôt que le simple contrôle de FC par bêta-bloquant retenu par certaines recommandations européennes. Test négatif → chirurgie.", "style": "cell"}]', 1),
(8, 'coronarien', 'Monter 1 à 2 étages, ménage — risque chirurgical estimé faible', 'Monter 1 à 2 étages, ménage', 1),
(9, 'diabete_perioperatoire_2025', '0,5 ≤ cétonémie ≤ 1,5 mmol/L ; cétonurie à 1 croix (si pH > 7,20 au GDS)', '0,5 ≤ cétonémie ≤ 1,5 mmol/L ; cétonurie à 1 croix (surveillance glycémie et cétonémie à H4) — même schéma si cétonémie > 1,5 mmol/L avec pH > 7,20 au GDS', 1),
(10, 'diabete_perioperatoire_2025', 'Cétonémie > 1,5 mmol/L ; cétonurie ≥ 2 croix, ou pH ≤ 7,20 au GDS', 'Cétonémie > 1,5 mmol/L ; cétonurie ≥ 2 croix', 1),
(11, 'diabete_perioperatoire_2025', 'Faire un GDS artériel, éliminer une autre cause d''acidose métabolique (hyperlactatémie, hyperchlorémie, hypercapnie) → transfert en USC pour insulinothérapie IVSE si pH ≤ 7,20', 'Faire un GDS artériel, éliminer une autre cause d''acidose métabolique (hyperlactatémie, hyperchlorémie, hypercapnie) → si pH > 7,20 : appliquer la ligne précédente (4 / 6 / 10 UI selon la glycémie), surveillance glycémie et cétonémie à H4 ; si pH ≤ 7,20 : transfert en USC pour insulinothérapie IVSE', 1),
(12, 'diabete_perioperatoire_2025', 'Échelle : 3,3-5 mmol/L (0,6-0,9 g/L) → 0 ; 5-10 mmol/L (0,9-1,8 g/L) → 0 ; 10-12 mmol/L (1,8-2,2 g/L) → 3 UI SC ; 12-16,5 mmol/L (2,2-3 g/L) → 4 UI SC ; &gt; 16,5 mmol/L (&gt; 3 g/L) → 6 UI SC (ou 1 ampoule G30 % IV / 15 g sucre PO si hypoglycémie associée).', 'Échelle : &lt; 3,3 mmol/L (&lt; 0,6 g/L) → 1 ampoule G30 % IV ou 15 g de sucre PO ; 3,3-5 mmol/L (0,6-0,9 g/L) → 0 ; 5-10 mmol/L (0,9-1,8 g/L) → 0 ; 10-12 mmol/L (1,8-2,2 g/L) → 3 UI SC ; 12-16,5 mmol/L (2,2-3 g/L) → 4 UI SC ; &gt; 16,5 mmol/L (&gt; 3 g/L) → 6 UI SC.', 1),
(13, 'diabete_perioperatoire_2025', 'selon l''échelle du protocole Basal Bolus (3,3-5 mmol/L → 0 ;', 'selon l''échelle du protocole Basal Bolus (&lt; 3,3 mmol/L → 1 ampoule G30 % IV ou 15 g de sucre PO ; 3,3-5 mmol/L → 0 ;', 1),
(14, 'diabete_perioperatoire_2025', '0,3 UI/kg/j SC à 20h (ou dose habituelle, ou 1/2 dose IV des dernières 24h).', '0,3 UI/kg/j SC à 20h (ou dose habituelle, ou 1/2 dose IV des dernières 24h), 30 UI maximum à l''initiation.', 1),
(15, 'hospit_ambulatoire', 'nés à terme, patients de plus de 3 mois (moins de 3 mois possibles selon l''expérience de l''équipe) ; nés prématurés, âge post-conceptionnel ≥60 semaines (jusqu''à 1 an possible selon l''expérience de l''équipe), <60 semaines = facteur d''exclusion.', 'nés à terme, patients de plus de 3 mois (certains patients de moins de 3 mois peuvent être inclus, selon l''expérience de l''équipe et la nature de l''intervention, après accord préalable anesthésiste/opérateur) ; nés prématurés, âge post-conceptionnel &lt;60 semaines = facteur d''exclusion ; au-delà, certains patients d''âge post-conceptionnel &gt;60 semaines et jusqu''à 1 an peuvent être inclus, selon l''expérience de l''équipe et la nature de l''intervention, après accord préalable anesthésiste/opérateur.', 1),
(16, 'curares', '[{"t": "p", "html": "R8.13", "style": "cell_b"}, {"t": "p", "html": "Il est recommandé de ne pas modifier la dose initiale en cas d''insuffisance rénale ou hépatique quel que soit le type de curare.", "style": "cell"}, {"t": "chip", "label": "1+"}]', '[{"t": "p", "html": "R8.13", "style": "cell_b"}, {"t": "p", "html": "Il est recommandé de ne pas modifier la dose initiale en cas d''insuffisance rénale ou hépatique quel que soit le type de curare.", "style": "cell"}, {"t": "chip", "label": "1-"}]', 1),
(17, 'aap_endoprotheses_coronaires', 'Pas d''argument en faveur d''une substitution par AINS (flurbiprofène 50 mg × 2, arrêt 24h avant) ou par HBPM à dose anticoagulante (85-100 UI Axa/kg/12h SC, non préventive) — substitution exposant elle-même à un risque hémorragique périopératoire non négligeable.', 'Si l''interruption totale est choisie, elle peut éventuellement conduire à une substitution (recommandation d''experts seulement) ; il n''existe pas plus d''argument en faveur d''une substitution par AINS (flurbiprofène 50 mg × 2, arrêt 24h avant) que par HBPM à dose anticoagulante (85-100 UI Axa/kg/12h SC, non préventive) — substitution exposant elle-même à un risque hémorragique périopératoire non négligeable.', 1),
(18, 'anesth_cardiopathie_congenitale', 'NYHA IV. Dysfonction ventriculaire sévère. Dilatation aortique sévère.', 'NYHA IV. Dilatation aortique sévère.', 1),
(19, 'anesth_cardiopathie_congenitale', 'Poursuite la veille ; arrêt le matin (≥ 12h si traitement de l''HTA) ; poursuite si insuffisance cardiaque et/ou FE ventricule systémique &lt; 40 %.', 'Poursuite la veille ; arrêt le matin ; poursuite si insuffisance cardiaque et/ou FE ventricule systémique &lt; 40 %.', 1),
(20, 'anesth_cardiopathie_congenitale', '[{"t": "p", "html": "Inhibiteurs SRAA", "style": "cell_b"}, {"t": "p", "html": "Poursuite la veille ; arrêt le matin ; poursuite si insuffisance cardiaque et/ou FE ventricule systémique &lt; 40 %.", "style": "cell"}]', '[{"t": "p", "html": "Inhibiteurs SRAA", "style": "cell_b"}, {"t": "p", "html": "Poursuite la veille ; arrêt le matin (≥ 12h si traitement de l''HTA) ; poursuite si insuffisance cardiaque et/ou FE ventricule systémique &lt; 40 %.", "style": "cell"}]', 1),
(21, 'antibioprophylaxie', 'V3.0 du 04/05/2026 (V1.0 originale du 08/12/2023 ; Champ 3 pédiatrique ajouté en V3.0).', 'V3.0 du 04/05/2026 (V1.0 originale du 08/12/2023 ; Champ 3 pédiatrique ajouté en V3.0). Une V3.1 du 10/07/2026 amende le Champ 3 pédiatrique (chirurgies digestives néonatales grêliques ou colorectales), hors du périmètre de cette fiche.', 1),
(22, 'aod_dabigatran_urgence_2016', 'Mesurer la concentration de dabigatran avant et 12-18 h après l''administration si la situation l''exige.', 'Dans tous les cas, un prélèvement pour mesurer la concentration de dabigatran avant l''administration doit être réalisé le plus tôt possible, sans que l''attente du résultat retarde l''antidote ; une nouvelle mesure 12-18 h après sera envisagée si la situation l''exige (ex. reprise du saignement).', 1),
(23, 'blocs_perimedullaires_complications_2006', 'En cas de brèche accidentelle évidente, il n''y a pas d''argument pour recommander un blood-patch préventif par le cathéter péridural posé dans un second temps.', 'En obstétrique, en cas de brèche accidentelle évidente, il n''y a pas d''argument pour recommander un blood-patch préventif par le cathéter péridural posé dans un second temps.', 1),
(24, 'blocs_perimedullaires_terrain_cardioresp_2006', 'En cas de cardiopathie dilatée, la baisse de la postcharge du VG induite par l''APM peut améliorer le volume d''éjection systolique malgré une diminution de la précharge ventriculaire.', 'En cas de cardiopathie dilatée, la baisse de la postcharge du VG induite par l''APM peut améliorer le volume d''éjection systolique malgré une diminution de la précharge ventriculaire. À l''inverse, le bloc sympathique induit par une APD thoracique peut déstabiliser une insuffisance cardiaque en diminuant la contractilité myocardique.', 1),
(25, 'blocs_peripheriques_membres', 'POA = [(PAS-PAD) × circonférence/largeur garrot] + PAD', 'POA = [(PAS-PAD) × circonférence du membre/(largeur du garrot × 3)] + PAD', 1),
(26, 'blocs_peripheriques_membres', '2 stimulations supérieures sur le radial (Grade E) ;', '2 stimulations : taux de réussite supérieur sur le radial et bloc moteur plus puissant que le canal huméral (non gradé) ;', 1),
(27, 'blocs_peripheriques_membres', 'Pas de contre-indication absolue chez un malade atteint d''une pathologie neurologique stable et bien étiquetée (Grade E).', 'Les complications neurologiques périphériques sont plus fréquentes après AG qu''après ALR (Grade B). Pas de contre-indication absolue chez un malade atteint d''une pathologie neurologique stable et bien étiquetée (Grade E).', 1),
(28, 'corticotherapie', 'Avant de débuter la corticothérapie (SDRA comme choc septique), rechercher systématiquement une infection ;', 'Au cours du SDRA, rechercher systématiquement une infection (systémique ou foyer, en particulier pulmonaire) avant de débuter la corticothérapie ;', 1),
(29, 'douleur_accouchement_2025', 'signes de toxicité aux AL ou douleur persistante/absence de niveau &gt; 45 min → arrêt et réévaluation complète.', 'signes de toxicité aux AL ou douleur persistante/absence de niveau &gt; 45 min malgré les mesures correctrices → repose de l''analgésie périmédullaire (cf. figure 4 de la source).', 1),
(30, 'douleur_postoperatoire', '[{"t": "p", "html": "Chez l''enfant : en dehors du syndrome de Fernand-Widal, on peut administrer des AINS aux enfants asthmatiques. Corriger les états de déshydratation/hypovolémie avant l''administration d''AINS.", "style": "cell"}, {"t": "chip", "label": "Fort"}]', '[{"t": "p", "html": "Chez l''enfant : en dehors du syndrome de Fernand-Widal, on peut administrer des AINS aux enfants asthmatiques.", "style": "cell"}, {"t": "chip", "label": "Faible"}], [{"t": "p", "html": "Chez l''enfant : corriger les états de déshydratation/hypovolémie avant l''administration d''AINS.", "style": "cell"}, {"t": "chip", "label": "Fort"}]', 1),
(31, 'douleur_reactualisation_2016', 'sur le cartilage (toxicité directe sur les chondrocytes).', 'sur le cartilage.', 1),
(32, 'echo_acces_vasculaires', 'du pneumothorax de 78 % et de l''hémothorax de 95 % (3 études, ~450-500 patients).', 'du pneumothorax de 78 % et de l''hémothorax de 95 % (échecs, ponctions artérielles et hématomes : 3 études, 498 patients ; pneumothorax : 2 études, 446 patients ; hémothorax : 1 étude, 401 patients).', 1),
(33, 'eclsa', '[{"t": "p", "html": "← TV, TP, FV (hors rythmes agoniques) réintègrent cette colonne depuis l''évaluation du rythme", "style": "ecls_a"}, {"t": "p", "html": "Évaluation de la durée de <b>low-flow</b>", "style": "ecls_a_head"}, {"t": "p", "html": "Évaluation du <b>rythme</b> → Asystole / rythme agonique = pas d''indication", "style": "ecls_a"}]', '[{"t": "p", "html": "", "style": "ecls_a"}, {"t": "p", "html": "Évaluation de la durée de <b>low-flow</b> (rejointe aussi par TV, TP, FV depuis l''évaluation du rythme)", "style": "ecls_a_head"}, {"t": "p", "html": "Évaluation du <b>rythme</b> → TV, TP, FV : vers l''évaluation de la durée de low-flow ; asystole / rythme agonique = pas d''indication", "style": "ecls_a"}]', 1),
(34, 'eer', '{"t": "p", "html": "Il ne semble pas utile d''utiliser une membrane à haute porosité (cut-off élevé) ou à forte capacité d''adsorption pour le traitement du choc septique.", "style": "cell"}', '{"t": "p", "html": "Il ne semble pas utile d''utiliser une membrane à haute porosité (cut-off élevé) ou à forte capacité d''adsorption pour le traitement du choc septique. (Avis d''experts)", "style": "cell"}', 1),
(35, 'eer', 'En SLED (hémodialyse intermittente prolongée à faible clairance), les débits de sang et de dialysat sont plus bas. (Avis d''experts)', 'En SLED (hémodialyse intermittente prolongée à faible clairance), il faut utiliser des débits de sang et de dialysat inférieurs. (Avis d''experts)', 1),
(36, 'erreurs_medicamenteuses_ar_2016', 'double lecture par une seconde personne ou seringues à code-barres en complément. Prévention des erreurs de voie : contrôle du point d''insertion, étiquetage spécifique par voie,', 'en complément, double lecture par une seconde personne ou seringues à code-barres lues avant injection, qui sont « peut-être des mesures efficaces ». Prévention des erreurs de voie : contrôle du point d''insertion, étiquetage spécifique par voie, absence de robinets sur les cathéters et tubulures d''ALR,', 1),
(37, 'erreurs_medicamenteuses_ar_2016', 'et possible au Guichet Erreurs Médicamenteuses de l''ANSM pour toute EM potentielle ou avérée sans événement indésirable.', 'et au Guichet Erreurs Médicamenteuses de l''ANSM, où toute EM potentielle ou avérée sans événement indésirable doit être déclarée directement par le professionnel.', 1),
(38, 'examens_pertinence_rea', '(Revised Cardiac Risk Index de Lee ≤1)', '(Revised Cardiac Risk Index de Lee à 1, selon la formulation de la source)', 1),
(39, 'gestion_traitements_chroniques_cardio_2009', 'électrodes en position antéropostérieure chez le porteur d''un DCI actif.', 'électrodes en position antéropostérieure chez le porteur d''un stimulateur ou d''un DCI dont la fonction antiarythmique est déprogrammée.', 1),
(40, 'gestion_traitements_chroniques_neuro_psy_2011', '[{"t": "p", "html": "IMAO ancienne gén.", "style": "cell_b"}, {"t": "p", "html": "Un traitement par IMAO ancienne génération (iproniazide) doit être maintenu avec une discussion pluridisciplinaire si le risque de décompensation psychiatrique apparaît important.", "style": "cell"}, {"t": "chip", "label": "AF"}]', '[{"t": "p", "html": "IMAO ancienne gén.", "style": "cell_b"}, {"t": "p", "html": "Un traitement par IMAO ancienne génération doit être maintenu avec une discussion pluridisciplinaire.", "style": "cell"}, {"t": "chip", "label": "AF"}], [{"t": "p", "html": "IMAO ancienne gén.", "style": "cell_b"}, {"t": "p", "html": "Un traitement par IMAO d''ancienne génération (iproniazide) peut être maintenu en période périopératoire si le risque de décompensation psychiatrique apparaît important.", "style": "cell"}, {"t": "chip", "label": "D"}]', 1),
(41, 'impact_environnemental_ag', 'En cas d''utilisation du protoxyde d''azote, préférer un système d''administration par bouteille plutôt que par cadres et circuit de distribution.', 'En cas d''utilisation du protoxyde d''azote, une alternative peut être d''utiliser un système d''administration par bouteille plutôt que par cadres et circuit de distribution.', 1),
(42, 'infarctus_myocarde', 'Fibrinolyse ; si échec fibrinolyse → angioplastie de sauvetage', 'Fibrinolyse ; si échec fibrinolyse → angioplastie de sauvetage ; si contre-indication à la thrombolyse → angioplastie primaire', 1),
(43, 'infections_intra_abdominales', 'EHPAD médicalisé + sonde/gastrotomie ;', 'EHPAD médicalisé ou soins de longue durée + sonde à demeure et/ou gastrostomie ;', 1),
(44, 'lat_soins_critiques', 'Le médecin en charge peut engager la procédure de sa propre initiative ou à la demande de la personne de confiance/famille/proches.', 'Le médecin en charge peut engager la procédure de sa propre initiative ; il est tenu de le faire à la demande de la personne de confiance ou, à défaut, de la famille ou de l''un des proches.', 1),
(45, 'lat_soins_critiques', 'R2.1, objectif habituel de sédation profonde = RASS -5, avec analgésie associée.', 'R2.1, cible de sédation profonde proposée par la HAS = RASS -4 ou -5 (RASS -5 dans les pratiques observées), avec analgésie associée.', 1),
(46, 'lat_soins_critiques', 'si une extubation est choisie, elle doit s''accompagner d''un protocole de sédation adapté pour prévenir les signes d''inconfort.', 'si une extubation est choisie, elle doit s''accompagner d''un protocole de sédation profonde et continue pour prévenir les signes d''inconfort.', 1),
(47, 'monitorage_traumatise', 'En milieu hostile, la dotation minimale comprend un petit oxymètre de pouls, un mini-tensiomètre électronique et un mini-cardioscope ou défibrillateur semi-automatique débrayable en mode manuel avec câble ECG 3 brins.', 'En milieu hostile, un petit oxymètre de pouls peut s''avérer utile (mesure de la SpO2 souvent perturbée dans ces conditions) ; la dotation pourra être complétée d''un mini-tensiomètre électronique et d''un mini-cardioscope ou défibrillateur semi-automatique débrayable en mode manuel avec câble ECG 3 brins.', 1),
(48, 'nutrition_perioperatoire', '71 recommandations sur 6 champs : évaluation de l''état nutritionnel, nutrition pré- et postopératoire, pharmaconutrition, obésité et chirurgie, diabète.', '71 recommandations sur 6 champs : évaluation de l''état nutritionnel, nutrition pré- et postopératoire, pharmaconutrition, obésité et chirurgie, diabète. La source suit une méthode non formalisée d''avis d''experts et n''imprime aucun grade : les grades affichés (1+, 2+, 1-, 2-) sont déduits de la formulation (« il faut » / « il faut probablement », à la forme positive ou négative).', 1),
(49, 'optimisation_beta_lactamines_2018', 'ou passer en perfusion continue à dose journalière égale, ou augmenter la dose unitaire.', 'ou passer en perfusion continue à dose journalière égale, ou augmenter la dose unitaire administrée de façon discontinue de 25 à 50 % en conservant la même fréquence, avec au besoin un bolus complémentaire.', 1),
(50, 'optimisation_beta_lactamines_2018', '<b>Tableau 1 — Cibles thérapeutiques par molécule (infection documentée) :</b>', '<b>Tableau 1 — Cibles thérapeutiques par molécule en phase probabiliste ou en infection non documentée (cibles calculées sur une CMI seuil) :</b>', 1),
(51, 'optimisation_beta_lactamines_2018', 'Cible visée (Cmin/Céq ≥ 4×CMI)', 'Cible visée (Cmin/Céq, 4 à 8 × CMI seuil)', 1),
(52, 'optimisation_beta_lactamines_2018', 'Colonne « infection non documentée » et notes de bas de tableau détaillées non reproduites ici — se référer au texte intégral (Tableau 1).', 'En infection documentée, la cible est une concentration résiduelle (ou à l''équilibre) libre ≥ 4 fois la CMI de la bactérie identifiée (4 à 8 fois), sans dépasser le plafond de toxicité propre à chaque molécule ; cette colonne et les notes de bas de tableau détaillées ne sont pas reproduites ici — se référer au texte intégral (Tableau 1).', 1),
(53, 'optimisation_beta_lactamines_2018', 'et le Tableau 1 des cibles par molécule (colonne « infection documentée »), mais condense l''argumentaire de chaque item, la colonne « infection non documentée » et les notes de bas de tableau détaillées,', 'et le Tableau 1 des cibles par molécule (colonne « infection non documentée », calculée sur une CMI seuil), mais condense l''argumentaire de chaque item, la colonne « infection documentée » et les notes de bas de tableau détaillées,', 1),
(54, 'organisation_anesthesie_pediatrique_2023', 'Risque majoré de complications respiratoires : MAR formé dédié + IADE à activité pédiatrique régulière dédié, OU MAR dédié seul avec second professionnel identifié à l''avance immédiatement disponible au bloc. Choix sous la responsabilité exclusive du MAR.', 'Risque majoré de complications respiratoires : MAR formé dédié + IADE à activité pédiatrique régulière dédié, OU MAR dédié seul avec second professionnel identifié à l''avance immédiatement disponible au bloc. Choix sous la responsabilité exclusive du MAR. Si une situation à risque élevé de complication respiratoire sévère est identifiée, quelle que soit l''organisation choisie : deux professionnels de l''anesthésie en pédiatrie, dont au moins un MAR, présents à l''induction et au réveil.', 1),
(55, 'preeclampsie', '<b>Rappel posologique du sulfate de magnésium</b> (protocole de référence des essais inclus dans l''argumentaire, notamment Magpie/étude de référence pour l''éclampsie) : dose de charge 4 g IV puis entretien — se référer au protocole local pour le débit d''entretien exact et la surveillance (réflexes ostéo-tendineux, diurèse, fréquence respiratoire).', '<b>Sulfate de magnésium :</b> la source cite les essais de référence (notamment Magpie) sans détailler de protocole — se référer au protocole local pour la posologie (dose de charge et entretien) et la surveillance (réflexes ostéo-tendineux, diurèse, fréquence respiratoire).', 1),
(56, 'raac_cardiaque_2021', 'et prendre un avis diabétologique pour améliorer le contrôle glycémique.', 'et, en cas de valeur &gt; 8 %, prendre un avis diabétologique pour améliorer le contrôle glycémique le plus en amont possible de la chirurgie (et au besoin la reporter selon le degré d''urgence).', 1),
(57, 'raac_cardiaque_2021', 'associée à une décontamination oropharyngée systématique par bain de bouche.', 'associée à une décontamination oropharyngée systématique par bain de bouche biquotidien à la chlorhexidine, débutées au moins 48 h avant la chirurgie, pour une durée totale de 5-7 jours.', 1),
(58, 'raac_cardiaque_2021', '(maintien/introduction précoce d''anti-arythmiques), pour diminuer le risque d''AVC postopératoire.', '(maintien/introduction précoce d''anti-arythmiques), pour diminuer le risque d''AVC postopératoire. En l''absence de contre-indication, bêtabloquants en première intention.', 1),
(59, 'remplissage', '<b>Hydroxyéthylamidons :</b> non recommandés en situation critique (sepsis, choc hémorragique) — signal de surmortalité/insuffisance rénale au cours du sepsis, absence de bénéfice et risque hémorragique au cours du choc hémorragique.', '<b>Hydroxyéthylamidons :</b> non recommandés au cours du sepsis (signal de surmortalité/insuffisance rénale) ; probablement pas recommandés au cours du choc hémorragique (recommandation optionnelle : absence de bénéfice et risque hémorragique).', 1),
(60, 'resection_hepatique_2025', 'hépatectomie mineure sur foie sain ou majeure (infiltration ± cathéter, bloc périphérique ± cathéter, ou péridurale) vs hépatectomie mineure sur foie cirrhotique', 'hépatectomie majeure (infiltration ± cathéter ou bloc périphérique ± cathéter, sans péridurale), hépatectomie mineure sur foie sain (infiltration ± cathéter, bloc périphérique ± cathéter, ou péridurale) et hépatectomie mineure sur foie cirrhotique', 1),
(61, 'resection_hepatique_2025', 'Bas grade (métastasectomie, mono-segmentectomie) ou grade intermédiaire (hépatectomie gauche, segmentectomies antéro-latérales, reconstruction biliaire) → étape suivante ; grade élevé (hépatectomie droite/centrale étendue ou non, segmentectomie postérieure complexe dont segment I ; sauf si cœlioscopie) → USIP directement.', 'Bas grade (métastasectomie, mono-segmentectomie) → SSPI (étape 5) puis service de chirurgie, sans passer par l''étape 4 ; grade intermédiaire (hépatectomie gauche, segmentectomies antéro-latérales, reconstruction biliaire) → étape suivante ; grade élevé (hépatectomie droite/centrale étendue ou non, segmentectomie postérieure complexe dont segment I) → USIP directement, sauf si cœlioscopie (→ étape suivante).', 1),
(62, 'sdra', 'la force résulte du niveau de preuve, de l''ampleur de l''effet, de la balance bénéfice/risque, des préférences et des coûts pris ensemble', 'la force résulte du processus d''analyse de la littérature et de gradation selon la méthode GRADE', 1),
(63, 'sdra', 'privilégier la ventilation protectrice et une prise en charge précoce en centre expert avant toute décision d''ECMO.', 'privilégier la ventilation protectrice et une prise en charge médicalisée la plus précoce possible avant toute décision d''ECMO.', 1),
(64, 'securisation_proc', '{"t": "p", "html": "En l''absence d''échec, l''arrêt de la VNI suppose au préalable une évaluation clinique et gazométrique de l''autonomie ventilatoire du patient en VS sur une période de 6 à 12 heures.", "style": "cell"}, {"t": "chip", "label": "Fort"}', '{"t": "p", "html": "En l''absence d''échec, l''arrêt de la VNI suppose au préalable une évaluation clinique et gazométrique de l''autonomie ventilatoire du patient en VS sur une période de 6 à 12 heures.", "style": "cell"}, {"t": "chip", "label": "?"}', 1),
(65, 'sedation_procedurale_2026', '{"t": "p", "html": "Il est recommandé de ne pas utiliser l''association midazolam + opiacés pour une sédation procédurale.", "style": "cell"}, {"t": "chip", "label": "1+"}', '{"t": "p", "html": "Il est recommandé de ne pas utiliser l''association midazolam + opiacés pour une sédation procédurale.", "style": "cell"}, {"t": "chip", "label": "1-"}', 1),
(66, 'sedation_procedurale_2026', 'pendant au moins les 30 premières minutes après la fin de la procédure.', 'après la fin de la procédure, notamment pendant les 30 premières minutes.', 1),
(67, 'sepsis_hemodynamique', '<b>Après la phase initiale</b> — poursuite du remplissage en utilisant des indices prédictifs dynamiques de l''état de réserve de précharge.', '<b>Après la phase initiale</b> — si le remplissage vasculaire doit être poursuivi, il doit s''effectuer en utilisant des indices prédictifs dynamiques de l''état de réserve de précharge (grade D).', 1),
(68, 'tabagisme', 'Le bénéfice augmente proportionnellement à la durée du sevrage, quel que soit le délai par rapport à l''intervention.', 'Le bénéfice augmente avec la durée du sevrage. L''arrêt du tabac périopératoire, quel que soit son délai par rapport à l''intervention, augmente la proportion d''arrêt définitif.', 1),
(69, 'tabagisme', 'un essai randomisé (hors contexte chirurgical) montre que la cigarette électronique multiplie par 2 le taux d''arrêt du tabac vs absence d''intervention, sans différence démontrée vs substituts nicotiniques (preuve de qualité basse).', 'une analyse de 3 essais randomisés contrôlés (1246 patients, hors contexte chirurgical) montre que la cigarette électronique multiplie par 2 le taux d''arrêt du tabac (preuve de qualité basse) ; l''absence de différence avec les substituts nicotiniques, observée dans un essai, est incertaine pour les mêmes raisons.', 1),
(70, 'tc_readaptation', '[{"t": "p", "html": "Q2.1", "style": "cell_b"}, {"t": "p", "html": "La TDM est l''examen de l''admission et de la 24e heure (diagnostic en urgence des lésions accessibles à un traitement neurochirurgical).", "style": "cell"}, {"t": "chip", "label": "AE"}]', '[{"t": "p", "html": "Q2.1", "style": "cell_b"}, {"t": "p", "html": "La TDM est l''examen de l''admission (diagnostic en urgence des lésions accessibles à un traitement neurochirurgical).", "style": "cell"}, {"t": "chip", "label": "B"}], [{"t": "p", "html": "Q2.1", "style": "cell_b"}, {"t": "p", "html": "La TDM est aussi l''examen de la 24e heure.", "style": "cell"}, {"t": "chip", "label": "AE"}]', 1),
(71, 'transfusion_plasma', '<b>Vérifié exhaustivement : 33 énoncés tagués dans le document — 6 Grade B, 11 Grade C, 16 accord professionnel, AUCUN Grade A.</b>', '<b>34 énoncés gradés dans le document — 7 Grade B (dont un imprimé « arade B », coquille de la source), 11 Grade C, 16 accord professionnel, aucun Grade A.</b>', 1),
(72, 'traumatisme_cranien', 'En cas de décision de traitement conservateur, il faut effectuer une surveillance clinique rapprochée dans un centre doté d''un service de neurochirurgie.', 'En cas de décision de traitement conservateur, il est probablement recommandé d''effectuer une surveillance clinique rapprochée dans un centre doté d''un service de neurochirurgie.', 1),
(73, 'urgences_obstetricales', '[{"t": "p", "html": "R4.1", "style": "cell_b"}, {"t": "p", "html": "Pré-éclampsie sévère hors structure spécialisée : appliquer la RFE SFAR/CNGOF 2020 (argumentaire R2.1/R2.2 du texte 2020).", "style": "cell"}, {"t": "chip", "label": "AE"}], [{"t": "p", "html": "R4.2", "style": "cell_b"}, {"t": "p", "html": "Pré-éclampsie sévère hors structure spécialisée : appliquer la RFE SFAR/CNGOF 2020 — <i>« R2.1 [2020] – Il est recommandé d''administrer systématiquement un traitement antihypertenseur chez les patientes avec une pré-éclampsie sévère présentant une PAS ≥ 160 mmHg et/ou une PAD ≥ 110 mmHg au repos et persistant durant plus de 15 minutes, et de maintenir la pression artérielle en dessous de ces seuils, pour réduire la survenue de complications maternelles, fœtales et néonatales sévères »</i>.", "style": "cell"}, {"t": "chip", "label": "1+"}], [{"t": "p", "html": "R4.3", "style": "cell_b"}, {"t": "p", "html": "Éclampsie hors structure spécialisée : appliquer la RFE SFAR/CNGOF 2020 — <i>« R2.8 [2020] – Il est recommandé d''administrer en anténatal du sulfate de magnésium aux femmes avec une pré-éclampsie sévère avec au moins un signe clinique de gravité afin de réduire le risque de survenue d''une éclampsie »</i> et <i>« R2.12 [2020] – Il est recommandé d''administrer du sulfate de magnésium en première intention chez des femmes ayant eu une crise d''éclampsie afin de réduire le risque de mortalité maternelle et le risque de récidive d''éclampsie »</i>.", "style": "cell"}, {"t": "chip", "label": "1+"}]', '[{"t": "p", "html": "R4.1", "style": "cell_b"}, {"t": "p", "html": "Pré-éclampsie sévère hors structure spécialisée : appliquer la RFE SFAR/CNGOF 2020 — <i>« R2.1 [2020] – Il est recommandé d''administrer systématiquement un traitement antihypertenseur chez les patientes avec une pré-éclampsie sévère présentant une PAS ≥ 160 mmHg et/ou une PAD ≥ 110 mmHg au repos et persistant durant plus de 15 minutes, et de maintenir la pression artérielle en dessous de ces seuils, pour réduire la survenue de complications maternelles, fœtales et néonatales sévères » (GRADE 1+)</i>. Décision et modalités du traitement antihypertenseur au mieux discutées par téléphone avec la structure spécialisée d''accueil.", "style": "cell"}, {"t": "chip", "label": "AE"}], [{"t": "p", "html": "R4.2", "style": "cell_b"}, {"t": "p", "html": "Pré-éclampsie sévère hors structure spécialisée : appliquer la RFE SFAR/CNGOF 2020 — <i>« R2.8 [2020] – Il est recommandé d''administrer en anténatal du sulfate de magnésium aux femmes avec une pré-éclampsie sévère avec au moins un signe clinique de gravité afin de réduire le risque de survenue d''une éclampsie » (GRADE 1+)</i>.", "style": "cell"}, {"t": "chip", "label": "AE"}], [{"t": "p", "html": "R4.3", "style": "cell_b"}, {"t": "p", "html": "Éclampsie hors structure spécialisée : appliquer la RFE SFAR/CNGOF 2020 — <i>« R2.12 [2020] – Il est recommandé d''administrer du sulfate de magnésium en première intention chez des femmes ayant eu une crise d''éclampsie afin de réduire le risque de mortalité maternelle et le risque de récidive d''éclampsie » (GRADE 1+)</i>.", "style": "cell"}, {"t": "chip", "label": "AE"}]', 1),
(74, 'traumatisme_vertebromedullaire', 'Pas d''immobilisation — transport sur matelas coquille.', 'Pas d''immobilisation.', 1),
(75, 'traumatisme_vertebromedullaire', 'Extraction sur plan dur + immobilisation cervicale (fixateur de tête).', 'Extraction sur plan dur + immobilisation cervicale (fixateur de tête), puis transport sur matelas coquille.', 1),
(76, 'traumatisme_vertebromedullaire', 'extraction sur plan dur seulement si urgence vitale ou critères cliniques présents, sinon pas d''immobilisation systématique (transport matelas coquille).', 'extraction sur plan dur puis transport sur matelas coquille si urgence vitale ou critères cliniques présents, sinon pas d''immobilisation systématique.', 1),
(77, 'urgences_ob_extrahosp', 'La source imprime « 100 à 500 mg/h » pour la posologie du sulprostone (p.657) — dose incompatible avec une utilisation clinique (surdosage massif). Lu et corrigé ici en <b>100 à 500 µg/h</b>, posologie standard du sulprostone (Nalador), cohérente avec un probable artefact d''extraction PDF « µ » → « m », même classe d''artefact que documentée ailleurs dans ce corpus (cf. fiche_sujet_age_esf.py) — disclosed plutôt que silencieusement résolu, conformément à la règle du projet.', 'Posologie habituelle du sulprostone selon la source : <b>100 à 500 µg/h</b>.', 1),
(78, 'vni', '[{"t": "p", "html": "Intérêt certain — Il faut faire (G1+)", "style": "cell"}, {"t": "p", "html": "Décompensation de BPCO • OAP cardiogénique • IRA hypoxémique de l''immunodéprimé • Post-opératoire de chirurgie thoracique et abdominale", "style": "cell"}], [{"t": "p", "html": "Intérêt non établi de façon certaine — Il faut probablement faire (G2+)", "style": "cell"}, {"t": "p", "html": "Stratégie de sevrage de la ventilation invasive chez les BPCO • Prévention d''une IRA post-extubation • Traumatisme thoracique fermé isolé • Décompensation de maladies neuromusculaires chroniques et autres IRC restrictives • Mucoviscidose décompensée • Forme apnéisante de la bronchiolite aiguë [pédiatrie] • Laryngo-trachéomalacie [pédiatrie]", "style": "cell"}]', '[{"t": "p", "html": "Intérêt certain — Il faut faire (G1+)", "style": "cell"}, {"t": "p", "html": "Décompensation de BPCO • OAP cardiogénique", "style": "cell"}], [{"t": "p", "html": "Intérêt non établi de façon certaine — Il faut probablement faire (G2+)", "style": "cell"}, {"t": "p", "html": "IRA hypoxémique de l''immunodéprimé • Post-opératoire de chirurgie thoracique et abdominale • Stratégie de sevrage de la ventilation invasive chez les BPCO • Prévention d''une IRA post-extubation • Traumatisme thoracique fermé isolé • Décompensation de maladies neuromusculaires chroniques et autres IRC restrictives • Mucoviscidose décompensée • Forme apnéisante de la bronchiolite aiguë [pédiatrie] • Laryngo-trachéomalacie [pédiatrie]", "style": "cell"}]', 1),
(79, 'mort_encephalique', '<b>Chronologie du PMO (telle que décrite par le texte source) :</b>', '<b>Chronologie du PMO (telle que décrite par le texte source) :</b> 1) exploration et préparation de l''étage abdominal ; 2) exploration et préparation de l''étage thoracique ; 3) héparinisation dix minutes avant le clampage et perfusion in situ (cotation 9) ; 4) prélèvement des organes thoraciques ; 5) prélèvement des organes abdominaux ; 6) prélèvement des tissus ; 7) restauration tégumentaire solide et esthétique.', 1),
(80, 'mort_encephalique', '[{"t": "p", "html": "2.6", "style": "cell_b"}, {"t": "p", "html": "Remplissage vasculaire (RV) modéré : cristalloïdes ou colloïdes indifféremment ; au-delà de 3 000 ml, utiliser les colloïdes plutôt que les cristalloïdes.", "style": "cell"}, {"t": "chip", "label": "7,5"}]', '[{"t": "p", "html": "2.6", "style": "cell_b"}, {"t": "p", "html": "Remplissage vasculaire (RV) modéré : cristalloïdes ou colloïdes indifféremment ; au-delà de 3 000 ml, utiliser les colloïdes plutôt que les cristalloïdes.", "style": "cell"}, {"t": "chip", "label": "7,5"}], [{"t": "p", "html": "2.6", "style": "cell_b"}, {"t": "p", "html": "Selon certaines études récentes, les hydroxyéthylamidons de dernière génération (poids moléculaire moyen, faible degré de substitution), à la posologie maximale de 30 ml/kg par jour, peuvent être utilisés indifféremment aux gélatines, sans risque d''atteinte rénale ; ces données doivent être confirmées.", "style": "cell"}, {"t": "chip", "label": "7"}]', 1),
(81, 'mort_encephalique', '[{"t": "p", "html": "3.4.2", "style": "cell_b"}, {"t": "p", "html": "Le diabète et l''HTA ne sont pas en soi des contre-indications ; l''éthylisme chronique ne contre-indique pas le prélèvement si le foie est macroscopiquement normal et sans altération biologique majeure ; une anomalie aiguë de la biologie hépatique (cytolyse) ne contre-indique pas non plus.", "style": "cell"}, {"t": "p", "html": "—", "style": "cell_c"}]', '[{"t": "p", "html": "3.4.2", "style": "cell_b"}, {"t": "p", "html": "Le diabète et l''HTA ne sont pas en soi des contre-indications ; une anomalie aiguë de la biologie hépatique (cytolyse) ne contre-indique pas non plus.", "style": "cell"}, {"t": "p", "html": "—", "style": "cell_c"}], [{"t": "p", "html": "3.4.2", "style": "cell_b"}, {"t": "p", "html": "L''éthylisme chronique ne contre-indique pas le prélèvement si le foie est macroscopiquement normal et si la biologie ne montre pas d''altérations majeures.", "style": "cell"}, {"t": "chip", "label": "8"}]', 1),
(82, 'mtev_perioperatoire', '[{"t": "p", "html": "HNF", "style": "gridd"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}], [{"t": "p", "html": "tinzaparine", "style": "gridd"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}], [{"t": "p", "html": "enoxaparine", "style": "gridd"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "½ dose", "style": "grid"}, {"t": "p", "html": "½ dose", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}], [{"t": "p", "html": "fondaparinux 2,5 mg", "style": "gridd"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}], [{"t": "p", "html": "apixaban / rivaroxaban", "style": "gridd"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}], [{"t": "p", "html": "dabigatran", "style": "gridd"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}, {"t": "p", "html": "", "style": "grid"}]', '[{"t": "p", "html": "HNF", "style": "gridd"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Non recommandé (GIHP)", "style": "grid"}, {"t": "p", "html": "Non recommandé (GIHP)", "style": "grid"}, {"t": "p", "html": "Non recommandé (GIHP)", "style": "grid"}, {"t": "p", "html": "Non recommandé (GIHP)", "style": "grid"}], [{"t": "p", "html": "tinzaparine", "style": "gridd"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}], [{"t": "p", "html": "enoxaparine", "style": "gridd"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Recommandé, ½ dose", "style": "grid"}, {"t": "p", "html": "Recommandé, ½ dose", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}], [{"t": "p", "html": "fondaparinux 2,5 mg", "style": "gridd"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}], [{"t": "p", "html": "apixaban / rivaroxaban", "style": "gridd"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}], [{"t": "p", "html": "dabigatran", "style": "gridd"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Non recommandé (AMM)", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}, {"t": "p", "html": "Recommandé", "style": "grid"}]', 1),
(83, 'mtev_perioperatoire', '<i>En rouge : non recommandé par l''AMM ; en orange : non recommandé par le GIHP ; en vert : recommandé.', '<i>Dans la source, ces mentions sont codées par couleur (rouge : non recommandé par l''AMM ; orange : non recommandé par le GIHP ; vert : recommandé).', 1),
(84, 'mtev_perioperatoire', '(reproduction verbatim du tableau-image source p.52)', '(d''après le tableau de la source, p. 52)', 1),
(85, 'mtev_perioperatoire', '[{"t": "p", "html": "-> Thromboprophylaxie par ANTICOAGULANT SEUL pendant toute la durée : HBPM, apixaban, dabigatran ou rivaroxaban, ou fondaparinux, débuté entre H12 et H24 post-opératoires (entre H6 et H12 si risque thromboembolique veineux élevé lié au patient — cf Q7 pour le détail des délais). Durée : 35 j (PTH) / 14 j (PTG).", "style": "body_sm"}, {"t": "chip", "label": "2+"}]', '[{"t": "p", "html": "-> Thromboprophylaxie par ANTICOAGULANT SEUL pendant toute la durée : HBPM, apixaban, dabigatran ou rivaroxaban, ou fondaparinux.", "style": "body_sm"}, {"t": "chip", "label": "1+"}], [{"t": "p", "html": "Débutée entre H12 et H24 post-opératoires (cf Q7 pour le détail des délais).", "style": "body_sm"}, {"t": "chip", "label": "2+"}], [{"t": "p", "html": "Entre H6 et H12 si risque thromboembolique veineux élevé lié au patient.", "style": "body_sm"}, {"t": "chip", "label": "AE"}], [{"t": "p", "html": "Durée : 35 j (PTH) / 14 j (PTG).", "style": "body_sm"}, {"t": "chip", "label": "1+"}]', 1),
(86, 'raac_colorectal', 'Oui en préopératoire de chirurgie carcinologique (recommandation principale). Non en préopératoire de chirurgie non carcinologique, non en postopératoire (recommandations secondaires).', 'Oui en préopératoire de chirurgie carcinologique ; non en préopératoire de chirurgie non carcinologique ; non en postopératoire (recommandations principales).', 1),
(87, 'raac_colorectal', 'Oui : optimisation de la volémie (principale). Non : apport excessif de solutés (secondaire).', 'Oui : optimisation de la volémie. Non : apport excessif de solutés (recommandations principales).', 1),
(88, 'raac_colorectal', 'Oui : dose unique de corticostéroïdes en préopératoire immédiat (secondaire).', 'Oui : dose unique de corticostéroïdes en préopératoire immédiat (principale).', 1),
(89, 'raac_colorectal', 'Oui, par la prévention de l''hypothermie peropératoire (principale) et l''antibioprophylaxie (secondaire).', 'Oui, par la prévention de l''hypothermie peropératoire et l''antibioprophylaxie (principales).', 1),
(90, 'raac_colorectal', 'Oui si anastomose sous-péritonéale (secondaire). Non si chirurgie colique (principale).', 'Oui si anastomose sous-péritonéale. Non si chirurgie colique (principales).', 1),
(91, 'raac_colorectal', 'Oui : mastication de gommes (secondaire). Non : administration de naloxone (secondaire).', 'Oui : mastication de gommes. Non : administration de naloxone (principales).', 1),
(92, 'raac_orthopedique_2019', '[{"t": "p", "html": "R10.2", "style": "cell_b"}, {"t": "p", "html": "Il est recommandé d''utiliser des techniques d''analgésie locale et/ou loco-régionale pour diminuer la douleur et la consommation de morphiniques après arthroplastie de genou.", "style": "cell"}, {"t": "chip", "label": "1+"}]', '[{"t": "p", "html": "R10.2", "style": "cell_b"}, {"t": "p", "html": "Il est recommandé d''utiliser des techniques d''analgésie locale et/ou loco-régionale pour diminuer la douleur et la consommation de morphiniques après arthroplastie de genou.", "style": "cell"}, {"t": "chip", "label": "1+"}], [{"t": "p", "html": "—", "style": "cell_b"}, {"t": "p", "html": "<b>Absence de recommandation</b> : données insuffisantes sur l''intérêt de l''analgésie locale ou locorégionale pour diminuer la douleur et/ou la consommation d''opiacés après arthroplastie de hanche dans un programme de réhabilitation.", "style": "cell"}, {"t": "p", "html": "—", "style": "cell_c"}]', 1),
(93, 'raac_orthopedique_2019', '<b>⚠ 3 incohérences du texte source, disclosed non résolues</b> (voir docstring du script pour le détail complet) :', '<b>⚠ 3 incohérences du texte source, signalées telles quelles :</b>', 1),
(94, 'raac_orthopedique_2019', 'alors que 3 portent la mention explicite « ABSENCE DE RECOMMANDATION » (Q2, Q3, Q7).', 'alors que 4 mentions explicites « ABSENCE DE RECOMMANDATION » figurent dans le texte (Q2, Q3, Q7, et l''analgésie après arthroplastie de hanche en Q10).', 1),
(95, 'raac_orthopedique_2019', 'et les 3 mentions « absence de recommandation »)', 'et les 4 mentions « absence de recommandation »)', 1),
(96, 'reduction_antibiotiques_reanimation_2014', 'quel que soit le site de prélèvement, dans le choix d''une antibiothérapie probabiliste.', 'quel que soit le site de prélèvement, dans le choix d''une antibiothérapie probabiliste pour une pneumonie acquise sous ventilation mécanique (PAVM) ou une bactériémie nosocomiale.', 1),
(97, 'reduction_antibiotiques_reanimation_2014', 'il ne faut pas prescrire de carbapénème sur le seul critère du caractère nosocomial de l''infection.', 'il ne faut pas prescrire de carbapénème sur le seul critère du caractère nosocomial de l''infection, mais plutôt considérer la présence d''au moins 2 des facteurs suivants : traitement antérieur par C3G, fluoroquinolone (dont monodose) ou pipéracilline-tazobactam dans les 3 mois ; portage d''une entérobactérie BLSE ou d''un P. aeruginosa caz-R sur un prélèvement de moins de 3 mois, quel que soit le site ; hospitalisation à l''étranger dans les 12 mois ; vie en EHPAD ou en soins de longue durée avec sonde à demeure et/ou gastrostomie ; épidémie en cours dans le secteur à BMR dont l''unique option thérapeutique est un carbapénème.', 1),
(98, 'reduction_antibiotiques_reanimation_2014', '(céfépime, pipéracilline-tazobactam, méropénème...) en perfusion prolongée/continue.', '(céfépime, pipéracilline-tazobactam, méropénème et doripénème) en perfusion intraveineuse « allongée » sur 3 ou 4 heures.', 1),
(99, 'reduction_antibiotiques_reanimation_2014', 'le traitement d''une bactériémie liée au cathéter si les hémocultures se négativent.', 'le traitement d''une bactériémie liée au cathéter si les hémocultures se négativent dans les trois premiers jours du traitement et que le cathéter a été retiré.', 1),
(100, 'sepsis', '[{"t": "p", "html": "<b>Cardiovasculaire</b> (0-6) — vasoactifs", "style": "cell_b"}, {"t": "p", "html": "0 traitement vasoactif, lactate &lt; 5 mmol/L", "style": "cell_sm_sepsis"}, {"t": "p", "html": "1 traitement vasoactif (1 pt/traitement, max 3)", "style": "cell_sm_sepsis"}, {"t": "p", "html": "≥ 2 traitements vasoactifs (2 pts/traitement, max 6)", "style": "cell_sm_sepsis"}, {"t": "p", "html": "Lactate ≥ 11 mmol/L", "style": "cell_sm_sepsis"}]', '[{"t": "p", "html": "<b>Cardiovasculaire</b> (0-6) — vasoactifs, lactate, PAM", "style": "cell_b"}, {"t": "p", "html": "0 traitement vasoactif, lactate &lt; 5 mmol/L, PAM au-dessus du seuil pour l''âge", "style": "cell_sm_sepsis"}, {"t": "p", "html": "1 point pour chaque critère (max 3) : 1 traitement vasoactif ; lactate 5-10,9 mmol/L ; PAM dans la zone « 1 point » pour l''âge", "style": "cell_sm_sepsis"}, {"t": "p", "html": "2 points pour chaque critère (max 6) : ≥ 2 traitements vasoactifs ; lactate ≥ 11 mmol/L ; PAM sous le seuil « 2 points » pour l''âge", "style": "cell_sm_sepsis"}, {"t": "p", "html": "—", "style": "cell_sm_sepsis"}]', 1),
(101, 'sepsis', '[{"t": "p", "html": "<b>Neurologique</b> (0-2)", "style": "cell_b"}, {"t": "p", "html": "Glasgow &gt; 10, pupilles réactives", "style": "cell_sm_sepsis"}, {"t": "p", "html": "—", "style": "cell_sm_sepsis"}, {"t": "p", "html": "Glasgow ≤ 10 ou pupilles fixes bilatérales = 2 pts", "style": "cell_sm_sepsis"}, {"t": "p", "html": "—", "style": "cell_sm_sepsis"}]', '[{"t": "p", "html": "<b>Neurologique</b> (0-2)", "style": "cell_b"}, {"t": "p", "html": "Glasgow &gt; 10, pupilles réactives", "style": "cell_sm_sepsis"}, {"t": "p", "html": "Glasgow ≤ 10 = 1 pt", "style": "cell_sm_sepsis"}, {"t": "p", "html": "Pupilles fixes bilatérales = 2 pts", "style": "cell_sm_sepsis"}, {"t": "p", "html": "—", "style": "cell_sm_sepsis"}]', 1),
(102, 'sepsis', 'Seuil PAM (mmHg) pour 1 pt cardiovasculaire, selon l''âge : &lt;1 mois &lt;30 ; 1-11 mois &lt;38 ; 1-&lt;2 ans &lt;43 ; 2-&lt;5 ans &lt;44 ; 5-&lt;12 ans &lt;48 ; 12-17 ans &lt;51.', 'PAM (mmHg) selon l''âge — 1 pt cardiovasculaire si : &lt;1 mois 17-30 ; 1-11 mois 25-38 ; 1-&lt;2 ans 31-43 ; 2-&lt;5 ans 32-44 ; 5-&lt;12 ans 36-48 ; 12-17 ans 38-51. 2 pts si : &lt;1 mois &lt;17 ; 1-11 mois &lt;25 ; 1-&lt;2 ans &lt;31 ; 2-&lt;5 ans &lt;32 ; 5-&lt;12 ans &lt;36 ; 12-17 ans &lt;51 (valeur imprimée telle quelle par la source, qui chevauche la zone 1 point : se référer au score de Phoenix original). 0 pt au-dessus de ces plages.', 1),
(103, 'tih', 'Recherche Ac anti-FP4 ; si résultat &lt; 3h, possibilité d''attendre avant de modifier le traitement', 'Recherche Ac anti-FP4 ; si résultat &lt; 3h, possibilité d''attendre avant de modifier le traitement ; si résultat en &gt; 3h, arrêt de l''héparine et relais par un anticoagulant non héparinique à dose curative', 1),
(104, 'tih', 'Ac négatifs → pas de TIH, reprendre l''héparine. Ac positifs → test fonctionnel → positif : TIH ; négatif : pas de TIH', 'Ac négatifs → pas de TIH, reprendre l''héparine. Ac positifs → poursuivre ou prescrire un anticoagulant non héparinique, puis test fonctionnel → positif : TIH ; négatif : pas de TIH', 1),
(105, 'traumatisme_membre', '[{"t": "p", "html": "Orientation (Fig. 3)", "style": "cell"}, {"t": "p", "html": "Chirurgie définitive sûre précoce", "style": "cell"}, {"t": "p", "html": "Réanimation appropriée, réévaluations répétées dans les 24h", "style": "cell"}, {"t": "p", "html": "Chirurgie définitive sûre retardée + stabilisation temporaire (si diaphyse de membre inférieur)", "style": "cell"}]', '[{"t": "p", "html": "Lésions associées / anatomiques", "style": "cell"}, {"t": "p", "html": "Lésions simples ou bénignes : lésion unique, Glasgow 13-15, lésion non hémorragique, ISS &lt; 25", "style": "cell"}, {"t": "p", "html": "Lésion anatomique à risque : ISS &gt; 25 ou une région avec AIS = 4 ; TC modéré (Glasgow ≤ 12) ; trauma thoracique sévère (TTS 8-11) ou contusion ≥ 2 lobes ; lésion aortique OIS 2 ; lésion abdominale OIS ≥ 3 avec hémopéritoine modéré ; hématome rétropéritonéal modéré (MTC ≥ 6) ; ischémie de membre réversible", "style": "cell"}, {"t": "p", "html": "Lésion anatomique sévère : ISS &gt; 40 ou AIS d''une région ≥ 5 ; TC grave (documenté à la TDM ou PIC ≥ 20 mmHg) ; trauma thoracique sévère (TTS ≥ 12) ; contusion pulmonaire ≥ 3 lobes ; lacération pulmonaire avec fuite massive ; lésion aortique OIS 3-4 non opérée ; lésion abdominale OIS ≥ 4 et/ou nécessitant une intervention hémostatique ; hématome rétropéritonéal abondant (MTC ≥ 10) ; fractures bilatérales de fémur ; fractures complexes et/ou diaphysaires multiples ; ischémie aiguë constituée d''un autre membre", "style": "cell"}], [{"t": "p", "html": "Chirurgie / intervention", "style": "cell"}, {"t": "p", "html": "—", "style": "cell"}, {"t": "p", "html": "Chirurgie lourde à risque : laparotomie simple ; ostéosynthèse du rachis en décubitus ventral ; ostéosynthèses orthopédiques multiples ; angio-embolisation préventive ; stenting endovasculaire", "style": "cell"}, {"t": "p", "html": "Intervention majeure nécessaire : craniectomie décompressive ; thoracotomie d''hémostase ou chirurgie de résection pulmonaire ; laparotomie « écourtée » ; packing pelvien ; fixateur externe de bassin à visée hémostatique ; angio-embolisation hémostatique", "style": "cell"}], [{"t": "p", "html": "Orientation (Fig. 3)", "style": "cell"}, {"t": "p", "html": "Chirurgie définitive sûre précoce", "style": "cell"}, {"t": "p", "html": "Réanimation appropriée, réévaluations répétées dans les 24h", "style": "cell"}, {"t": "p", "html": "Chirurgie définitive sûre retardée + stabilisation temporaire (si diaphyse de membre inférieur)", "style": "cell"}]', 1),
(106, 'traumatisme_membre', 'si allergie : clindamycine ± gentamicine', 'si allergie : clindamycine + gentamicine', 1);
